// Lấy toàn bộ đối tượng item từ node trước
const item = items[0].json;

// Lấy mảng 'Outline' từ bên trong key 'output'
const outlineArray = item.output.Outline;

// --- 1. Tạo chuỗi văn bản 'formattedOutline' ---
// (Phần này giữ nguyên, nó vẫn sẽ bao gồm H2 cuối cùng)
const formattedText = outlineArray.map(h2_item => {

    // Lấy tiêu đề H2
    let h2_block = "H2: " + h2_item.heading2;

    // Lấy các tiêu đề H3 con (nếu có)
    let h3_lines = "";
    if (h2_item.subheadings && h2_item.subheadings.length > 0) {

        h3_lines = h2_item.subheadings.map(h3_item => 
            "    H3: " + h3_item.heading3
        ).join('\n');
    }

    // Kết hợp H2 và H3
    if (h3_lines) {
        return h2_block + '\n' + h3_lines;
    }
    return h2_block; 

}).join('\n\n');

// --- 2. TẠO MẢNG CHỈ CÓ HEADING 2 (BỎ CÁI CUỐI CÙNG) ---
// Thêm .slice(0, -1) ở cuối dòng này
const h2List = outlineArray.map(h2_item => h2_item.heading2).slice(0, -1);

// --- 3. Thêm cả hai trường mới vào 'output' ---
item.output.formattedOutline = formattedText;
item.output.h2List = h2List; // <-- Dòng này tạo ra mảng H2 đã bỏ H2 cuối

// Trả về TOÀN BỘ đối tượng 'item' (đã được cập nhật)
return item;
